using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Text;using System.Threading;using System.Windows.Automation;
namespace Iris {
    sealed partial class NativeDiscordSurface : IDiscordSurface {
        static readonly string[] muteNames={"Stummschalten","Stummschaltung aufheben","Mute","Unmute"};
        static readonly string[] deafenNames={"Ein- und Ausgabe deaktivieren","Ein- und Ausgabe aktivieren","Deafen","Undeafen"};
        static readonly string[] areaNames={"Benutzerstatus und Einstellungen","User status and settings","User area","Benutzerbereich"};
        static readonly string[] shareNames={"Bildschirm übertragen","Bildschirm teilen","Bildschirmübertragung starten","Share Your Screen","Share your screen","Screen Share"};
        readonly List<IntPtr> windows;readonly int clientCount;readonly IntPtr ownedFixture;
        public NativeDiscordSurface(){windows=new List<IntPtr>();var clients=new HashSet<string>(StringComparer.OrdinalIgnoreCase);EnumWindows(delegate(IntPtr window,IntPtr arg){if(!IsWindowVisible(window)||GetWindowTextLength(window)==0)return true;string path=Image(window);if(path==null)return true;clients.Add(path);windows.Add(window);return true;},IntPtr.Zero);clientCount=clients.Count;windows=windows.OrderByDescending(IsMain).ToList();}
        // Native UIA contract tests may only target a window owned by this very
        // process. This cannot be used to redirect QA actions to a foreign app.
        internal NativeDiscordSurface(IntPtr fixture){uint pid;GetWindowThreadProcessId(fixture,out pid);if(pid!=(uint)System.Diagnostics.Process.GetCurrentProcess().Id)throw new InvalidOperationException("QA target must belong to Iris");ownedFixture=fixture;windows=new List<IntPtr>{fixture};clientCount=1;}
        bool TargetWindow(IntPtr window){if(ownedFixture==IntPtr.Zero)return Image(window)!=null;uint pid;GetWindowThreadProcessId(window,out pid);return window==ownedFixture&&pid==(uint)System.Diagnostics.Process.GetCurrentProcess().Id;}
        static bool IsMain(IntPtr window){var title=new StringBuilder(512);GetWindowText(window,title,title.Capacity);return title.ToString().EndsWith("Discord",StringComparison.OrdinalIgnoreCase)||title.ToString().EndsWith("Discord PTB",StringComparison.OrdinalIgnoreCase)||title.ToString().EndsWith("Discord Canary",StringComparison.OrdinalIgnoreCase);}
        static string Image(IntPtr window){uint pid;GetWindowThreadProcessId(window,out pid);var handle=OpenProcess(0x1000,false,pid);if(handle==IntPtr.Zero)return null;try{var path=new StringBuilder(32768);int length=path.Capacity;if(!QueryFullProcessImageName(handle,0,path,ref length))return null;string name=Path.GetFileName(path.ToString());return new[]{"Discord.exe","DiscordPTB.exe","DiscordCanary.exe"}.Contains(name,StringComparer.OrdinalIgnoreCase)?path.ToString():null;}finally{CloseHandle(handle);}}
        void Check(){if(windows.Count==0)throw new InvalidOperationException(L.T("Discord hat kein geöffnetes Fenster. Öffne die Discord-Desktop-App."));if(clientCount>1||windows.Count(IsMain)>1)throw new InvalidOperationException(L.T("Mehrere Discord-Clients sind geöffnet. Lass für die Steuerung nur einen Client geöffnet."));}
        static Condition Names(string[] names){return new OrCondition(names.Select(n=>(Condition)new PropertyCondition(AutomationElement.NameProperty,n,PropertyConditionFlags.IgnoreCase)).ToArray());}
        static AutomationElement Area(AutomationElement root){return root.FindFirst(TreeScope.Descendants,Names(areaNames));}
        static bool? State(AutomationElement element,string op){object pattern;if(element.TryGetCurrentPattern(TogglePattern.Pattern,out pattern)){var value=((TogglePattern)pattern).Current.ToggleState;return value==ToggleState.Indeterminate?(bool?)null:value==ToggleState.On;}
            // A switch's constant aria-label is never proof of state. Only an
            // action-labelled Button may use a paired Mute/Unmute name fallback.
            if(element.Current.ControlType!=ControlType.Button)return null;string name=element.Current.Name??"";string[] names=op=="mute"?muteNames:deafenNames;int i=Array.FindIndex(names,n=>string.Equals(n,name,StringComparison.OrdinalIgnoreCase));return i<0?(bool?)null:i%2==1;}
        public DiscordSwitch Read(string op,string scope){Check();foreach(var window in windows){if(scope!=null&&scope!=window.ToInt64().ToString(System.Globalization.CultureInfo.InvariantCulture))continue;if(!TargetWindow(window))continue;var root=AutomationElement.FromHandle(window);var area=Area(root);if(area==null&&IsMain(window))continue;var elements=(area??root).FindAll(TreeScope.Descendants,Names(op=="mute"?muteNames:deafenNames));var candidates=new List<AutomationElement>();foreach(AutomationElement element in elements){object pattern;if(element.TryGetCurrentPattern(TogglePattern.Pattern,out pattern)||element.Current.ControlType==ControlType.Button&&element.TryGetCurrentPattern(InvokePattern.Pattern,out pattern))candidates.Add(element);}var switches=candidates.Where(e=>{object p;return e.TryGetCurrentPattern(TogglePattern.Pattern,out p);}).ToArray();if(switches.Length>0)candidates=switches.ToList();if(candidates.Count!=1)continue;var selected=candidates[0];return new DiscordSwitch{Scope=window.ToInt64().ToString(System.Globalization.CultureInfo.InvariantCulture),Identity=string.Join(".",selected.GetRuntimeId()),State=State(selected,op),Enabled=selected.Current.IsEnabled,Native=selected};}return null;}
        public void Toggle(string op,DiscordSwitch before,CancellationToken token,Action sent){token.ThrowIfCancellationRequested();var current=Read(op,before.Scope);if(current==null||current.Identity!=before.Identity||current.State!=before.State||!current.Enabled)throw new InvalidOperationException(L.T("Der Discord-Schalter hat sich geändert. Es wurde nichts geschaltet; bitte erneut versuchen."));var element=(AutomationElement)current.Native;object pattern;token.ThrowIfCancellationRequested();if(element.TryGetCurrentPattern(TogglePattern.Pattern,out pattern)){sent();((TogglePattern)pattern).Toggle();}else if(element.TryGetCurrentPattern(InvokePattern.Pattern,out pattern)){sent();((InvokePattern)pattern).Invoke();}else throw new InvalidOperationException(L.T("Discord unterstützt diese Schaltfläche nicht über Windows."));}
        static string Url(AutomationElement element){object pattern;return element.TryGetCurrentPattern(ValuePattern.Pattern,out pattern)?((ValuePattern)pattern).Current.Value:null;}
        public DiscordReply Inspect(CancellationToken token){Check();var reply=DiscordReply.Of("ok","");foreach(var window in windows.Where(IsMain)){token.ThrowIfCancellationRequested();if(TargetWindow(window))ReadTextNavigation(AutomationElement.FromHandle(window),reply,token);}var mute=Read("mute",null);var deafen=Read("deafen",null);reply.Message=L.T("Mikrofon: ")+Description(mute)+L.T(" · Ein-/Ausgabe: ")+Description(deafen)+L.T(". Eingelesen werden nur zugängliche Textkanäle des geöffneten Servers und sichtbare Direktnachrichten.");return reply;}
        static string Description(DiscordSwitch value){return value==null||!value.State.HasValue?L.T("nicht lesbar"):value.State.Value?L.T("stumm"):L.T("an");}
        static string SafeName(string value,string fallback){value=(value??"").Trim();if(value.Length==0)return fallback;return value.Length>120?value.Substring(0,120):value;}
        public void Share(CancellationToken token,Action sent){Check();foreach(var window in windows){token.ThrowIfCancellationRequested();if(!TargetWindow(window))continue;var root=AutomationElement.FromHandle(window);var area=Area(root);if(area==null&&IsMain(window))continue;area=area??root;var active=area.FindFirst(TreeScope.Descendants,Names(new[]{"Streaming beenden","Stop Streaming","Stop streaming"}));if(active!=null)throw new InvalidOperationException(L.T("In Discord läuft bereits eine Bildschirmübertragung. Iris beendet oder wechselt sie nicht automatisch."));var elements=area.FindAll(TreeScope.Descendants,Names(shareNames));foreach(AutomationElement element in elements){object pattern;if(element.Current.IsEnabled&&element.TryGetCurrentPattern(InvokePattern.Pattern,out pattern)){token.ThrowIfCancellationRequested();sent();((InvokePattern)pattern).Invoke();return;}}}throw new InvalidOperationException(L.T("Keine zugängliche Freigabe-Schaltfläche. Öffne Discord und tritt zuerst einem Sprachkanal bei."));}
        delegate bool EnumProc(IntPtr window,IntPtr arg);
        [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc callback,IntPtr arg);
        [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
        [DllImport("user32.dll")]static extern int GetWindowTextLength(IntPtr window);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr window,StringBuilder text,int length);
        [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
        [DllImport("kernel32.dll")]static extern IntPtr OpenProcess(uint access,bool inherit,uint pid);
        [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool QueryFullProcessImageName(IntPtr process,int flags,StringBuilder name,ref int length);
        [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
    }
}
